                        {field(
                          "Username",
                          "person-circle",
                          username,
                          setUsername,
                          { autoComplete: "username", returnKeyType: "next" },
                        )}
                        {route === "signup" &&
                          field("Email", "mail", email, setEmail, {
                            keyboardType: "email-address",
                            autoComplete: "email",
                          })}
                        {field(
                          "Password",
                          "lock-closed",
                          password,
                          setPassword,
                          {
                            secureTextEntry: true,
                            autoComplete: "off",
                            onSubmitEditing:
                              route === "login" ? login : undefined,
                          },
                        )}
                        {route === "signup" &&
                          field(
                            "Repeat password",
                            "lock-closed",
                            repeat,
                            setRepeat,
                            {
                              secureTextEntry: true,
                              autoComplete: "off",
                              onSubmitEditing: signup,
                            },
                          )}
